 static long
c300_call_zapamcom10050_proc (zapamcom10140_io_t *itf)
{
     long                rc = RC_NRM;

    if (itf->in.non_auth_yn[0] == 'Y')       /* UKEY2.0 */
    {

        strncpy(itf->out.auth_cl_cd, "3", LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD);

    } else
    {
        zapamcom10050_io_t  zapamcom10050_io;

        memset( &zapamcom10050_io , 0x00 , sizeof( zapamcom10050_io_t ) );   /* 구조체 초기화  */

        /* 모듈호출 입력 정보  구조체에 설정 */
        zapamcom10050_io.in.acnt_num = itf->in.acnt_num; /* 계정번호  */

    /* --- DB암호화 적용 start --- */
    //    strncpy(zapamcom10050_io.in.bank_card_num, itf->in.bank_card_num, LEN_ZAPAMCOM10050_IN_BANK_CARD_NUM) ;   /* 계좌번호 */
        zapamcom10050_io.in.bank_card_ser_num = itf->in.bank_card_ser_num ;   /* 계좌일련번호 */
    /* --- DB암호화 적용 end --- */

        strncpy(zapamcom10050_io.in.bank_card_co_cd, itf->in.bank_card_co_cd, LEN_ZAPAMCOM10050_IN_BANK_CARD_CO_CD) ; /* 은행코드 */

        strncpy(zapamcom10050_io.in.pay_mthd_cd, itf->in.pay_mthd_cd, LEN_ZAPAMCOM10050_IN_PAY_MTHD_CD) ; /* 납부방법 */

    /* --- DB암호화 적용 start --- */
    //    strncpy(zapamcom10050_io.in.drw_bank_ctz_num, itf->in.drw_bank_ctz_num, LEN_ZAPAMCOM10050_IN_DRW_BANK_CTZ_NUM) ; /*인출계좌주민등록번호*/
        zapamcom10050_io.in.drw_bank_ctz_ser_num = itf->in.drw_bank_ctz_ser_num;  /*인출계좌주민등록일련번호*/
    /* --- DB암호화 적용 end --- */

        /* 회사 구분 코드 U.key 2.0 */
        strncpy(zapamcom10050_io.in.co_cl_cd, itf->in.co_cl_cd, LEN_ZAPAMCOM10050_IN_CO_CL_CD );

       /* 금결원 계좌인증만 해야하는경우 'Y'    20130628 추가  */
       if ((strncmp(itf->in.deal_id, "ZEQPSBIZ00610_TR06", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || /* 20130628 추가 */
           (strncmp(itf->in.deal_id, "ZAPASCRT60010_TR84", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || /* 2018.09.19 금결원 계좌인증만 함(T-GATE용) */
            ( (strncmp(itf->in.co_cl_cd, "T", LEN_ZAPAMCOM10140_IN_CO_CL_CD ) == RC_NRM) &&
              ( (strncmp(itf->in.deal_id, "ZPAYSTRM20100_TR03", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) ||   /* 2017.11.30 */
                (strncmp(itf->in.deal_id, "ZPAYSREG00100_TR13", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) ||   /* 2021.06.30 - 구독서비스Prj 계좌인증(렌탈) 추가 */
                (strncmp(itf->in.deal_id, "ZPAYSREG00420_TR04", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) ||   /* 2023.02.22 구독고도화 Prj  박희철 구독이용권 환불계좌인증 추가 */
                (strncmp(itf->in.deal_id, "ZPAYSREG00420_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) ||   /* 2022.0825 구독고도화 Prj  박희철 구독서비스 환불계좌인증 추가*/
                (strncmp(itf->in.deal_id, "ZPAYSOVRN0900_TR82", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) )    /* 2025.04.28 SKT N서비스 Prj 과납 환불계좌인증 추가 */

            )
          )
        {
            strncpy( zapamcom10050_io.in.kftc_only_auth_yn , "Y" , LEN_ZAPAMCOM10050_IN_KFTC_ONLY_AUTH_YN);
        }

        /* 2019.09.26 edi_fb_cl_cd = 'K' 인경우 kftc_only_auth_yn=Y 로 하여 ksnet인증 하도록함 */
        if (strncmp(itf->in.edi_fb_cl_cd, "K", LEN_ZAPAMCOM10140_IN_EDI_FB_CL_CD ) == RC_NRM)
        {
            strncpy( zapamcom10050_io.in.kftc_only_auth_yn , "Y" , LEN_ZAPAMCOM10050_IN_KFTC_ONLY_AUTH_YN);
            strncpy(zapamcom10050_io.in.edi_fb_cl_cd       , "E" , LEN_ZAPAMCOM10050_IN_EDI_FB_CL_CD) ;
        }else
        {
            strncpy(zapamcom10050_io.in.edi_fb_cl_cd, itf->in.edi_fb_cl_cd, LEN_ZAPAMCOM10050_IN_EDI_FB_CL_CD) ; /* EDI/FB 구분 2019.04.25 SKT 인출제도개선PJT */
        }
        strncpy(zapamcom10050_io.in.user_id     , itf->in.audit_id    , LEN_ZAPAMCOM10050_IN_USER_ID     ) ;/*reqr or userid 2019.04.25 SKT 인출제도개선PJT*/

        PRINT_ZAPAMCOM10050_IN_T(&zapamcom10050_io.in);

        rc = mpfm_dlcall("zapamcom10050",  (void *) &zapamcom10050_io);
        if (rc != RC_NRM)
        {
            PFM_ERRS(" zapamcom10050 call error : [%ld] ", rc );
            return RC_ERR;
        }

        /* 공통 부분 */
        PRINT_ZAPAMCOM10050_OUT_T(&(zapamcom10050_io.out));

        strncpy(itf->out.auth_cl_cd, zapamcom10050_io.out.auth_cl_cd, LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD) ; /* 인증구분코드 */

        // 2018.10.25 카드무인증프로세스추가 Start
        // 납부방법이 카드이고, 카드비밀번호가 공란이 아니면 외부인증으로 처리한다.
        if ( (atoi(itf->in.pay_mthd_cd) == 2) && (mpfm_isspnull( itf->in.pwd) != RC_NRM) )
        {
            itf->out.auth_cl_cd[0] = '2';
        }

        // 카드번호체크모듈에서 무인증->외부인증으로 설정한 것을 회선체크후에도 다시 설정해준다.
        // 아래 경우는 외부기관(카드사)장애로 무인증이라 하더라도 외부인증으로 다시 설정한다.
        /* 20060320 추가작업 만약 로밍에서 호출되었느데 외부인증이 아닌경우 로직부여 예상으로인해 */
        /******************************************************************************************
         *
         * 아래는 매우중요한 사안임 로밍에서 호출되는경우 Prefix 체크후 외부인증이 아니더라도 외부인증으로 해야한다.
         * 왜냐면 로밍은 무조건적으로 prefix만 정상이라면 인증을 받아야 함으로 인해서
         * TCB 카드인증인 경우도 외부인증을 태워야 한다.
           2018.10.25 카드무인증프로세스추가로 아래 서비스와 모듈에서 호출되는 경우에는 외부인증으로 처리한다.
         * 2020.10.29 카드무인증처리 채널 확대. 외부인증 처리에서 제외함.([티월드,사이버고객센터], [SKB ARS Self], [SKT ARS Self])
         * ****************************************************************************************/
          /* 2020.10.29 외부인증 처리에서 제외함. 주석처리 */
                 //(strncmp(itf->in.deal_id, "ZAPASCRT30060_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // SKB ARS SELF 자동납부 신청
                 //(strncmp(itf->in.deal_id, "ZAPASCRT30060_TR04", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // SKB ARS SELF 자동납부 변경
                 //(strncmp(itf->in.deal_id, "ZAPASCRT30010_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // T-World,사이버신청
                 //(strncmp(itf->in.deal_id, "ZAPASCRT30010_TR04", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // T-World,사이버변경
                 //(strncmp(itf->in.deal_id, "ZAPASCRT30090_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 2020.08.13 ARSSELF 카드신청
                 //(strncmp(itf->in.deal_id, "ZAPASCRT30090_TR04", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM)    // 2020.08.13 ARSSELF 카드변경
        if ( atoi(itf->in.pay_mthd_cd) == 2 ) {  // 납부방법이 카드자동납부이면
            if ( (atol(itf->in.op_cl) == 3) ||
                 (strncmp(itf->in.deal_id, "ZAPASCRT60010_TR81", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // TCB카드인증
                 (strncmp(itf->in.deal_id, "ZPAYSADV00600_TR82", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // PPS데이터자동충전정보처리
                 (strncmp(itf->in.deal_id, "ZPAYSADV01000_TR03", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // PPS자동충전신청변경(e-Station)
                 (strncmp(itf->in.deal_id, "ZPAYSADV09000_TR15", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 콘텐츠이용료 자동선결제 카드사 인증
                 (strncmp(itf->in.deal_id, "ZPAYSADV09000_TR95", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 소액결제 이용료 자동선결제 카드사 인증
                 (strncmp(itf->in.deal_id, "ZPAYSPMT00510_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 간편결제 원장 등록
                 (strncmp(itf->in.deal_id, "ZAPAMCOM80030"     , LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 외부기관 신규가입호출용 모듈
                 (strncmp(itf->in.deal_id, "ZPAYSEDI60020_TR04", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 2020.07.02 유효멤버쉽 카드인증
                 (strncmp(itf->in.deal_id, "ZPAYSREG00100_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 2021.06.30 구독서비스 카드인증 추가
                 (strncmp(itf->in.deal_id, "ZPAYSREG00100_TR13", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 2021.06.30 구독서비스 카드인증 추가
                 (strncmp(itf->in.deal_id, "ZPAYSREG00420_TR04", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) || // 2023.02.22 구독고도화 Prj  박희철 구독이용권 환불계좌인증 추가
                 (strncmp(itf->in.deal_id, "ZPAYSREG00420_TR02", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM)    /* 2022.08.25 구독고도화 Prj  박희철 구독서비스 환불계좌인증 추가*/
                )
            {
                 itf->out.auth_cl_cd[0] = '2';
            }
        }
        // 2018.10.25 카드무인증프로세스추가 End

        /* 2018.09.19  T-GATE용 계좌인증(ZAPASCRT60010_TR84) 은 내부인증없다. - 외부인증으로 변환 */
        if ((strncmp(itf->in.deal_id, "ZAPASCRT60010_TR84", LEN_ZAPAMCOM10140_IN_DEAL_ID ) == RC_NRM) &&
            (zapamcom10050_io.out.auth_cl_cd[0] == '1')
           )
        {
            strncpy(itf->out.auth_cl_cd, "2", LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD);
        }
    }   /* UKEY2.0 */

    /* UKEY2.0 - start */
    if (strncmp(itf->in.co_cl_cd, "B", LEN_ZAPAMCOM10140_IN_CO_CL_CD ) == RC_NRM)      /* UKEY2.0 */
    {
        if (itf->out.auth_cl_cd[0] == '1')
        {
            strncpy(itf->out.auth_cl_cd, "2", LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD);
        }

        if (itf->in.non_auth_yn[0] == 'Y') /* UKEY2.0 */
        {
            strncpy(itf->out.auth_cl_cd, "3", LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD);
        }
    }
    /* UKEY2.0 - end */

    /********************************************************************
     * 2008/03/06 <>> 중요함.
     * <>> SK-VAN 실시간은행원장등록 이면서 신규가입인 경우
     *       실시간계좌인증처리 없이 정상처리하도록 처리함.
     ********************************************************************/
    /* 2019.04.25 SKT 인출제도개선PJT : EDI/FB 구분처리 - START */
	if (strncmp( gc_edi_bank_yn  , "Y",  LEN_LC_COMM_CD_ID ) == RC_NRM ||
		strncmp( gc_skvan_bank_yn, "Y",  LEN_LC_COMM_CD_ID ) == RC_NRM )
	{
		/* 호출한 프로그램명이 신규가입(ZAPASCRT10030_TR01) 이거나
		*  T-WORLD신규가입(ZAPASCRT30020_TR02) 인 경우는 무인증이면서 결과값을 정상으로 리턴한다. */
		if ((strncmp(itf->in.deal_id, "ZAPASCRT10030_TR01",  LEN_ZAPAMCOM10140_IN_DEAL_ID) == RC_NRM ) ||
			(strncmp(itf->in.deal_id, "ZAPASCRT30020_TR02",  LEN_ZAPAMCOM10140_IN_DEAL_ID) == RC_NRM ) ||
			(strncmp(itf->in.deal_id, "ZAPAMCOM80030"     ,  LEN_ZAPAMCOM10140_IN_DEAL_ID) == RC_NRM )) /* 2018.01.11 오상록 - 해당 모듈에서 호출될때도 무인증처리 하도록 변경 */
		{
			/* 인증유형코드 */
			strncpy(itf->out.auth_cl_cd, "3", LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD);
			/*인증결과코드*/
			strncpy(itf->in.rltm_auth_rslt_cd  ,"SKIP"    ,LEN_ZAPAMCOM10140_IN_RLTM_AUTH_RSLT_CD );
			/*실시간인증결과반영여부*/
			strncpy(itf->out.rltm_auth_rslt_aply_yn, "Y" ,  LEN_ZAPAMCOM10140_OUT_RLTM_AUTH_RSLT_APLY_YN) ;
			/* 결과코드 -  EDI / SK-VAN 무인증 : 'S'(SKIP), 그이외는 'N'(NORMAL) */
			strncpy(itf->out.result_cd, "S", LEN_ZAPAMCOM10140_OUT_RESULT_CD );

			return RC_NRM;
		}
	}
    /* 2019.04.25 SKT 인출제도개선PJT : EDI/FB 구분처리 - END */


    /* 외부인증인경우 다음로직으로 분기하기 위하여 */
    if (strncmp(itf->out.auth_cl_cd, "2",  LEN_ZAPAMCOM10140_OUT_AUTH_CL_CD) == RC_NRM )
    {
        return RC_NRM;
    }
    /* 2018.09.19 ZAPASCRT60010_TR84(TGATE 계좌인증) 인경우 무인증일때  실시간인증이력테이블에 insert 하지 않는다.        */
    /*            apascrt60010t84 에서 별로도 insert zpay_ap_rltm_auth_hst 함 (max(일련번호)로 insert 하지 않기 위해서 )  */
    if (strncmp(itf->in.deal_id, "ZAPASCRT60010_TR84",  LEN_ZAPAMCOM10140_IN_DEAL_ID) == RC_NRM )
    {
        return RC_NRM;
    }

    /* ******************************************
     * 은행은 내부1, 외부2 , 무인증3이 허용되나
     * 카든 외부2, 무인증만 허용된다
     * 내부 (IN00) 외부(SKIP)
     * ------------------------------------------
     * 2008/03/06 수정사항
     * => 실시간은행원장등록의 경우 내부 (IN00) 인증처리 없음.
     * *****************************************/
    if (atoi(itf->in.pay_mthd_cd) == 1)
